+ <script>
+ (function() {
+ // Session state
+ const startTime = Date.now();
+ let tasks = [];
+ let logs = [];
+ let memory = [];
+ let vaultLocal = [];
+ let vaultRemote = [];
+ let llmConnected = false;
+ let lastActionTime = Date.now();
+ let autopilotActive = false;
+ // DOM refs
+ const tierEls = document.querySelectorAll('.tier');
+ const llmSelect = document.getElementById('llmSelect');
+ const connectBtn = document.getElementById('connectBtn');
+ const llmStatus = document.getElementById('llmStatus');
+ const tokenCount = document.getElementById('tokenCount');
+ const llmInput = document.getElementById('llmInput');
+ const sendBtn = document.getElementById('sendBtn');
+ const llmOutput = document.getElementById('llmOutput');
+ const ritualSelect = document.getElementById('ritualSelect');
+ const ritualTrigger = document.getElementById('ritualTrigger');
+ const audioToggle = document.getElementById('audioToggle');
+ const glowToggle = document.getElementById('glowToggle');
+ const nightToggle = document.getElementById('nightToggle');
+ const typewriterToggle = document.getElementById('typewriterToggle');
+ const autopilotToggle = document.getElementById('autopilotToggle');
+ const taskList = document.getElementById('taskList');
+ const logList = document.getElementById('logList');
+ const saveTasksBtn = document.getElementById('saveTasks');
+ const clearTasksBtn = document.getElementById('clearTasks');
+ const saveLogBtn = document.getElementById('saveLog');
+ const clearLogBtn = document.getElementById('clearLog');
+ const devInfo = document.getElementById('devInfo');
+ const phaseSelect = document.getElementById('phaseSelect');
+ const injectScriptBtn = document.getElementById('injectScript');
+ const scanInterfaceBtn = document.getElementById('scanInterface');
+ const activateModuleBtn = document.getElementById('activateModule');
+ const localPane = document.getElementById('localPane');
+ const vaultPane = document.getElementById('vaultPane');
+ const saveVaultBtn = document.getElementById('saveVault');
+ const loadVaultBtn = document.getElementById('loadVault');
+ const chatFileInput = document.getElementById('chatFile');
+ const playChatBtn = document.getElementById('playChat');
+ const injectMemoryBtn = document.getElementById('injectMemory');
+ const exportSessionBtn = document.getElementById('exportSession');
+ const exportLogBtn = document.getElementById('exportLog');
+ const exportVaultBtn = document.getElementById('exportVault');
+ const exportMemoryBtn = document.getElementById('exportMemory');
+ const neuroDropBtn = document.getElementById('neuroDropExport');
+ const tearExportBtn = document.getElementById('tearExport');
+ const burnToggle = document.getElementById('burnToggle');
+ const chatArea = document.getElementById('chatArea');
+ const sessionStartSpan = document.getElementById('sessionStart');
+ const sessionRuntimeSpan = document.getElementById('sessionRuntime');
+ const devHoursSpan = document.getElementById('devHours');
+ const qrContainer = document.getElementById('qrContainer');
+ // Timers
+ let chatPlaybackInterval = null;
+ let autopilotInterval = null;
+ // Initialise UI
+ sessionStartSpan.textContent = `Started: ${new Date(startTime).toLocaleString()}`;
+ setInterval(() => {
+ const seconds = Math.floor((Date.now() - startTime) / 1000);
+ const hrs = Math.floor(seconds / 3600);
+ const mins = Math.floor((seconds % 3600) / 60);
+ const secs = seconds % 60;
+ sessionRuntimeSpan.textContent = `Runtime: ${hrs}h ${mins}m ${secs}s`;
+ devHoursSpan.textContent = `Dev Hours: ${(seconds / 3600).toFixed(2)}`;
+ }, 1000);
+ // Load vault from localStorage if present
+ function loadVault() {
+ try {
+ const data = JSON.parse(localStorage.getItem('neuralVault') || '{}');
+ vaultLocal = data.local || [];
+ vaultRemote = data.remote || [];
+ } catch (e) {
+ vaultLocal = [];
+ vaultRemote = [];
+ }
+ renderVault();
+ }
+ function saveVault() {
+ const data = { local: vaultLocal, remote: vaultRemote };
+ localStorage.setItem('neuralVault', JSON.stringify(data));
+ log('Vault saved');
+ }
+ saveVaultBtn.addEventListener('click', saveVault);
+ loadVaultBtn.addEventListener('click', loadVault);
+ // Render vault lists
+ function renderVault() {
+ localPane.innerHTML = '<h4>Local</h4>';
+ vaultPane.innerHTML = '<h4>Vault</h4>';
+ vaultLocal.forEach(item => {
+ localPane.appendChild(createFileItem(item.name, item.locked));
+ });
+ vaultRemote.forEach(item => {
+ vaultPane.appendChild(createFileItem(item.name, item.locked));
+ });
+ }
+ // Save and update after drop events
+ function updateVaultState() {
+ vaultLocal = [];
+ vaultRemote = [];
+ localPane.querySelectorAll('.fileItem').forEach(el => {
+ vaultLocal.push({ name: el.dataset.name, locked: el.classList.contains('locked') });
+ });
+ vaultPane.querySelectorAll('.fileItem').forEach(el => {
+ vaultRemote.push({ name: el.dataset.name, locked: el.classList.contains('locked') });
+ });
+ }
+ // Connect LLM (auto detect on load)
+ async function autoDetectLLM() {
+ try {
+ const resp = await fetch('http://127.0.0.1:11434');
+ if (resp.ok) {
+ llmStatus.textContent = 'Ollama Detected';
+ llmStatus.style.color = 'var(--highlight)';
+ }
+ } catch (e) {
+ // remain disconnected
+ }
+ }
+ autoDetectLLM();
+ connectBtn.addEventListener('click', () => {
+ if (!llmConnected) {
+ llmConnected = true;
+ llmStatus.textContent = `Connected to ${llmSelect.options[llmSelect.selectedIndex].text}`;
+ llmStatus.style.color = 'var(--highlight)';
+ log(`Connected to ${llmSelect.value}`);
+ }
+ });
+ // Send LLM command
+ sendBtn.addEventListener('click', () => {
+ const cmd = llmInput.value.trim();
+ if (!cmd) return;
+ lastActionTime = Date.now();
+ log(`LLM prompt: ${cmd}`);
+ addTask(`LLM: ${cmd}`);
+ appendChatMessage(cmd, 'user');
+ llmInput.value = '';
+ const start = Date.now();
+ updateStatus('thinking');
+ sendLLM(cmd).then(resp => {
+ const duration = (Date.now() - start) / 1000;
+ updateStatus('done');
+ const tokens = countTokens(resp);
+ tokenCount.textContent = `${tokens} tokens`; 
+ appendChatMessage(resp, 'system');
+ log(`LLM response (${tokens} tokens, ${duration.toFixed(1)}s): ${resp}`);
+ });
+ detectTier(cmd);
+ });
+ // Ritual trigger
+ ritualTrigger.addEventListener('click', () => {
+ const ritual = ritualSelect.value;
+ log(`Ritual triggered: ${ritual}`);
+ addTask(`Ritual: ${ritual}`);
+ triggerRitual(ritual);
+ });
+ // Toggle actions
+ audioToggle.addEventListener('change', () => {
+ log(`Audio FX ${audioToggle.checked ? 'enabled' : 'disabled'}`);
+ });
+ glowToggle.addEventListener('change', () => {
+ log(`Glow FX ${glowToggle.checked ? 'enabled' : 'disabled'}`);
+ });
+ nightToggle.addEventListener('change', () => {
+ document.body.classList.toggle('nightvision', nightToggle.checked);
+ log(`Night vision ${nightToggle.checked ? 'on' : 'off'}`);
+ });
+ typewriterToggle.addEventListener('change', () => {
+ log(`Typewriter mode ${typewriterToggle.checked ? 'on' : 'off'}`);
+ });
+ autopilotToggle.addEventListener('change', () => {
+ autopilotActive = autopilotToggle.checked;
+ if (autopilotActive) {
+ startAutopilot();
+ log('Autopilot enabled');
+ } else {
+ stopAutopilot();
+ log('Autopilot disabled');
+ }
+ });
+ // Task memory actions
+ saveTasksBtn.addEventListener('click', () => {
+ downloadFile('task_history.txt', tasks.map(t => t.desc).join('\n'));
+ });
+ clearTasksBtn.addEventListener('click', () => {
+ tasks = [];
+ renderTasks();
+ });
+ saveLogBtn.addEventListener('click', () => {
+ downloadFile('session_log.txt', logs.join('\n'));
+ });
+ clearLogBtn.addEventListener('click', () => {
+ logs = [];
+ renderLogs();
+ });
+ // Dev info update
+ setInterval(() => {
+ devInfo.textContent = `Tasks: ${tasks.length}, Logs: ${logs.length}, Memory: ${memory.length}`;
+ }, 2000);
+ phaseSelect.addEventListener('change', () => {
+ log(`Phase view set to ${phaseSelect.value}`);
+ });
