+ injectScriptBtn.addEventListener('click', () => {
+ log('DOM AI: injected script');
+ addTask('DOM AI inject');
+ tierFlash();
+ });
+ scanInterfaceBtn.addEventListener('click', () => {
+ const modules = document.querySelectorAll('details').length;
+ log(`DOM AI: scanned interface (${modules} modules)`);
+ addTask(`DOM AI scan: ${modules} modules`);
+ });
+ activateModuleBtn.addEventListener('click', () => {
+ log('DOM AI: activated module');
+ addTask('DOM AI activate');
+ flashChat();
+ });
+ // Vault drag/drop and decrypt
+ [localPane, vaultPane].forEach(pane => {
+ pane.addEventListener('dragover', evt => {
+ evt.preventDefault();
+ pane.classList.add('dragover');
+ });
+ pane.addEventListener('dragleave', () => {
+ pane.classList.remove('dragover');
+ });
+ pane.addEventListener('drop', evt => {
+ evt.preventDefault();
+ pane.classList.remove('dragover');
+ const data = evt.dataTransfer.getData('text/plain');
+ const item = document.getElementById(data);
