+ pane.appendChild(item);
+ updateVaultState();
+ log(`Moved ${item.dataset.name} to ${pane.id === 'localPane' ? 'Local' : 'Vault'}`);
+ addTask(`File moved: ${item.dataset.name}`);
+ }
+ });
+ });
+ function createFileItem(name, locked) {
+ const div = document.createElement('div');
+ div.textContent = name;
+ div.className = 'fileItem' + (locked ? ' locked' : '');
+ div.dataset.name = name;
+ div.id = `file-${name.replace(/[^a-zA-Z0-9_-]/g, '')}-${Math.random().toString(36).substr(2, 5)}`;
+ div.draggable = !locked;
+ if (!locked) {
+ div.addEventListener('dragstart', evt => {
+ evt.dataTransfer.setData('text/plain', div.id);
+ });
+ }
+ // decrypt button for locked files
+ const btn = document.createElement('button');
+ btn.textContent = locked ? 'Decrypt' : 'Open';
+ btn.addEventListener('click', evt => {
+ evt.stopPropagation();
+ if (locked) {
+ div.classList.remove('locked');
+ btn.textContent = 'Open';
+ log(`Decrypted ${name}`);
+ } else {
+ log(`Opened ${name}`);
+ }
+ updateVaultState();
+ });
+ div.appendChild(btn);
+ return div;
+ }
