+ if (vaultLocal.length === 0 && vaultRemote.length === 0) {
+ vaultLocal = [ { name:'notes.txt', locked:false }, { name:'todo.md', locked:false }, { name:'log.json', locked:false } ];
+ vaultRemote = [ { name:'core.fuse', locked:true }, { name:'secret.lock', locked:true }, { name:'project.zip', locked:false } ];
+ }
+ renderVault();
+ }
+ initVault();
+ // Chat import and memory injection
+ playChatBtn.addEventListener('click', () => {
+ const files = chatFileInput.files;
+ if (!files || files.length === 0) return;
+ Array.from(files).forEach(file => {
+ const reader = new FileReader();
+ reader.onload = e => {
+ const text = e.target.result;
+ let messages = [];
+ try {
+ const data = JSON.parse(text);
+ if (Array.isArray(data)) messages = data;
+ } catch (err) {
+ messages = text.split(/\r?\n/).filter(Boolean);
+ }
+ simulateChatPlayback(messages);
+ };
+ reader.readAsText(file);
+ });
+ });
+ injectMemoryBtn.addEventListener('click', () => {
+ const files = chatFileInput.files;
+ if (!files || files.length === 0) return;
+ Array.from(files).forEach(file => {
+ const reader = new FileReader();
+ reader.onload = e => {
+ const text = e.target.result;
+ let messages = [];
+ try {
+ const data = JSON.parse(text);
+ if (Array.isArray(data)) messages = data;
+ } catch (err) {
+ messages = text.split(/\r?\n/).filter(Boolean);
+ }
+ memory = memory.concat(messages);
+ log(`Injected ${messages.length} messages to memory`);
+ };
+ reader.readAsText(file);
+ });
+ });
+ // Export system
+ exportSessionBtn.addEventListener('click', () => {
+ const lines = [];
+ lines.push(`# Session Summary`);
+ lines.push(`Start Time: ${new Date(startTime).toLocaleString()}`);
+ lines.push(`Runtime: ${sessionRuntimeSpan.textContent.replace('Runtime: ', '')}`);
+ lines.push(`Dev Hours: ${devHoursSpan.textContent.replace('Dev Hours: ', '')}`);
+ lines.push(`\n## Tasks`);
+ tasks.forEach(t => lines.push(`- ${t.desc}`));
+ lines.push(`\n## Logs`);
+ logs.forEach(l => lines.push(`- ${l}`));
+ downloadFile('session_summary.md', lines.join('\n'));
+ });
+ exportLogBtn.addEventListener('click', () => {
+ downloadFile('logs.txt', logs.join('\n'));
+ });
+ exportVaultBtn.addEventListener('click', () => {
+ const data = JSON.stringify({ local: vaultLocal, remote: vaultRemote }, null, 2);
+ downloadFile('vault.json', data);
+ });
+ exportMemoryBtn.addEventListener('click', () => {
+ const data = `/* LLM memory stub */\nconst memory = ${JSON.stringify(memory, null, 2)};`;
+ downloadFile('memory.js', data);
+ });
+ neuroDropBtn.addEventListener('click', () => {
+ const htmlCopy = document.documentElement.outerHTML;
+ const blob = new Blob([htmlCopy], { type: 'text/html' });
+ downloadBlob(blob, 'NeuroDrop_export.html');
+ });
+ tearExportBtn.addEventListener('click', () => {
+ // .tear packaging: embed html and data into one JSON blob then encode
+ const payload = {
