[tool] // src/modules/vaultEncryption.js // Implements secure saving and loading of the session state and console // log via AES encryption. Uses the CryptoJS library which must be // loaded into the page via a <script> tag in renderer.html. import { state } from './state.js'; import { gainXP } from './xpSystem.js'; import { append } from './memoryTimeline.js'; /** * Prompt the user for an encryption key and return it. Returns * undefined if the user cancelled. * @param {string} message */ function promptForKey(message) { const key = prompt(message); if (!key || key.trim().length === 0) return undefined; return key.trim(); } /** * Gather the current console log. Supports both textarea and div * based consoles. */ function getConsoleLog() { const consoleOut = document.getElementById('consoleOutput') || document.getElementById('consoleBox'); if (!consoleOut) return ''; if (consoleOut.tagName.toLowerCase() === 'textarea') { return consoleOut.value; } return consoleOut.textContent || ''; } /** * Append text to the console output, respecting the element type. */ function appendConsole(text) { const consoleOut = document.getElementById('consoleOutput') || document.getElementById('consoleBox'); if (!consoleOut) return; if (consoleOut.tagName.toLowerCase() === 'textarea') { consoleOut.value += text; consoleOut.scrollTop = consoleOut.scrollHeight; } else { consoleOut.textContent += text; } } /** * Encrypt the current state and console log to a .vault file. */ async function encryptData(plainText, passphrase) { const enc = new TextEncoder(); const dec = new TextDecoder(); const salt = window.crypto.getRandomValues(new Uint8Array(16)); const iv = window.crypto.getRandomValues(new Uint8Array(12)); const keyMaterial = await window.crypto.subtle.importKey( 'raw', enc.encode(passphrase), 'PBKDF2', false, ['deriveKey'] ); const key = await window.crypto.subtle.deriveKey( { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' }, keyMaterial, { name: 'AES-GCM', length: 256 }, false, ['encrypt'] ); const cipherBuf = await window.crypto.subtle.encrypt( { name: 'AES-GCM', iv }, key, enc.encode(plainText) ); // Concatenate salt + iv + ciphertext const combined = new Uint8Array(salt.length + iv.length + cipherBuf.byteLength); combined.set(salt, 0); combined.set(iv, salt.length); combined.set(new Uint8Array(cipherBuf), salt.length + iv.length); // Convert to base64 string return btoa(String.fromCharCode(...combined)); } async function decryptData(base64, passphrase) { const enc = new TextEncoder(); const data = Uint8Array.from(atob(base64), c => c.charCodeAt(0)); const salt = data.slice(0, 16); const iv = data.slice(16, 28); const cipherBuf = data.slice(28).buffer; const keyMaterial = await window.crypto.subtle.importKey( 'raw', enc.encode(passphrase), 'PBKDF2', false, ['deriveKey'] ); const key = await window.crypto.subtle.deriveKey( { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' }, keyMaterial, { name: 'AES-GCM', length: 256 }, false, ['decrypt'] ); const plainBuf = await window.crypto.subtle.decrypt( { name: 'AES-GCM', iv }, key, cipherBuf ); return new TextDecoder().decode(plainBuf); } async function saveVault() { const key = promptForKey('Enter encryption key for vault:'); if (!key) return; try { const payload = { state, logs: getConsoleLog() }; const plainText = JSON.stringify(payload); const cipherText = await encryptData(plainText, key); const filePath = await window.appAPI.saveFileDialog('session.vault'); if (!filePath) return; await window.neuralAPI.writeFile(filePath, cipherText); append('Vault Save', filePath); gainXP(5); appendConsole('
[Vault saved to ' + filePath + ']
'); } catch (err) { alert('Vault save failed: ' + err.message); } } /** * Decrypt a .vault file and merge the contained state back into the * application. Updates the UI automatically via state listeners. */ async function loadVault() { const filePath = await window.neuralAPI.selectFile(); if (!filePath) return; const key = promptForKey('Enter decryption key for vault:'); if (!key) return; try { const cipherText = await window.neuralAPI.readFile(filePath); const plain = await decryptData(cipherText, key); const payload = JSON.parse(plain); if (payload.state) { if (typeof payload.state.tier !== 'undefined') state.tier = payload.state.tier; if (typeof payload.state.xp !== 'undefined') state.xp = payload.state.xp; if (typeof payload.state.role !== 'undefined') state.role = payload.state.role; if (typeof payload.state.rank !== 'undefined') state.rank = payload.state.rank; if (typeof payload.state.theme !== 'undefined') state.theme = payload.state.theme; } if (payload.logs) { appendConsole('
