um)) { state.tier = Math.max(0, Math.min(5, num)); notify(); } } /** * Increment XP by the specified amount. Negative values are ignored. * @param {number} amount */ function addXP(amount) { const inc = parseInt(amount, 10); if (!isNaN(inc) && inc > 0) { state.xp += inc; notify(); } } /** * Set the current role (e.g. 'Founder', 'Sentinel'). No validation * is performed here; other modules decide when roles may change. * @param {string} r */ function setRole(r) { state.role = r; notify(); } /** * Set the UI theme. Accepts strings corresponding to CSS file names * defined in src/themes. This function does not itself apply the * styles – that is handled by the themeSwitcher module – but it * persists the choice to settings. * @param {string} theme */ function setTheme(theme) { state.theme = theme; notify(); } export { state, load, save, onChange, setTier, addXP, setRole, setTheme };
