+// -----------------------------------------------------------------------------
+// Vault encryption bridge
+//
+// The renderer cannot access Node.js APIs directly. To support AES‑256
+// encryption of the session vault we expose helper methods here that
+// leverage the built‑in `crypto` module. A passphrase is hashed via
+// SHA‑256 to derive a 32 byte key. A random 16 byte IV is used for
+// each encryption. The resulting ciphertext is returned along with the
+// base64‑encoded IV separated by a colon. Decryption performs the
+// inverse operation and returns the original plaintext. Should the
+// caller supply an invalid passphrase or corrupt data an exception
+// will propagate to the renderer for handling.
+try {
+ const crypto = require('crypto');
+ contextBridge.exposeInMainWorld('vaultAPI', {
+ /**
+ * Encrypt the provided plaintext using AES‑256‑CBC. Derives a key
+ * by hashing the passphrase with SHA‑256 and prepends the IV to
+ * the ciphertext separated by a colon.
+ *
+ * @param {string} plainText
+ * @param {string} passphrase
+ * @returns {string} Base64 encoded string containing IV and ciphertext
+ */
+ encrypt: (plainText, passphrase) => {
+ const key = crypto.createHash('sha256').update(String(passphrase)).digest();
+ const iv = crypto.randomBytes(16);
+ const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);
+ let encrypted = cipher.update(String(plainText), 'utf8', 'base64');
+ encrypted += cipher.final('base64');
+ return `${iv.toString('base64')}:${encrypted}`;
+ },
+ /**
+ * Decrypt a ciphertext produced by the encrypt() method above. Expects
+ * the IV and ciphertext separated by a colon. If decryption
+ * fails the error will be thrown to the caller.
+ *
+ * @param {string} cipherText
+ * @param {string} passphrase
+ * @returns {string}
+ */
+ decrypt: (cipherText, passphrase) => {
+ const [ivB64, data] = String(cipherText).split(':');
+ const key = crypto.createHash('sha256').update(String(passphrase)).digest();
+ const iv = Buffer.from(ivB64, 'base64');
+ const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
+ let decrypted = decipher.update(String(data), 'base64', 'utf8');
+ decrypted += decipher.final('utf8');
+ return decrypted;
+ }
+ });
+} catch (err) {
+ // In rare cases (e.g. missing crypto module) we silently
+ // omit the vault API. The renderer will fall back to its
